from pathlib import Path
import re
p=Path(__file__).parent;c=p/'crossrail'
def setbody(n,s):
 f=p/f'reassembled/slide_{n:02}.html';h=f.read_text();h=re.sub(r'(?s)(<div class="body">).*(</div></div></section>)',lambda m:m[1]+s+m[2],h);f.write_text(h)
def slot(s,col,span,row,rows):
 i=s.index('>');return s[:i]+f' style="grid-column:{col} / span {span};grid-row:{row} / span {rows}"'+s[i:]
def tab(rows,heads=None):return '<div class="tablebox" data-el="crossrail-table"><table class="table">'+('<thead><tr>'+''.join('<th>'+x+'</th>' for x in heads)+'</tr></thead>' if heads else '')+'<tbody>'+''.join('<tr>'+''.join('<td>'+x+'</td>' for x in r)+'</tr>' for r in rows)+'</tbody></table></div>'
# Equipment photos, letter badges and a real four-row key/value table are independent elements.
a=[]
for i,col in enumerate([1,5,9]):
 a+=[slot('<div class="frame" data-el="crossrail-image-frame"><div class="seat avatar" data-ph="'+str(i+1)+'"></div></div>',col,4,1,3),slot('<div class="pill line" data-el="crossrail-pill"><div class="parts"><p class="name">'+'ABC'[i]+'</p></div></div>',col,4,1,3),slot(tab([['장비 명','제조 장비'],['제조회사','미리 컴퍼니'],['고유 번호','00011110'],['모델명','Miri-00000']]),col,4,4,3)]
setbody(15,''.join(a))
s='[data-el="crossrail-image-frame"]:has(>.seat.avatar)';f=c/'elements/image-frame/element.css';f.write_text(f.read_text()+f'\n{s}{{flex:none;align-self:center;justify-self:center;box-sizing:border-box;width:188px;height:188px;max-width:100%;max-height:100%;border:2px solid var(--n-3);border-radius:50%;padding:7px;transform:translateY(calc(var(--gap-sm)/-3))}}{s}::before{{display:none}}{s} .seat{{border-radius:50%}}\n')
s='[data-el="crossrail-pill"].line:not(:has(.mark,.note))';f=c/'elements/pill/element.css';f.write_text(f.read_text()+f'\n{s}{{width:42px;height:42px;max-height:42px;flex:none;justify-self:center;align-self:start;margin-left:146px;transform:translateY(calc(var(--gap-sm)/-4));padding:0;background:var(--a1-7);border:0;color:var(--page)}}{s} .name{{font-family:var(--crossrail-font-label);font-size:var(--type-18);color:inherit}}\n')
s='[data-el="crossrail-table"]:not(:has(thead)):not(:has(tr>td:nth-child(3)))';f=c/'elements/table/element.css';f.write_text(f.read_text()+f'''\n{s} .table{{border:0;table-layout:fixed}}{s} td{{height:47px;box-sizing:border-box;padding:0 0 0 calc(var(--gap) + var(--gap-sm)/3);border:0;border-bottom:1px solid var(--n-3);font-size:var(--type-18);font-weight:var(--body-weight);color:var(--ink);text-align:left}}{s} td:first-child{{width:137px;font-weight:var(--name-weight)}}{s}:has(tr:nth-child(6)){{padding-left:var(--pad)}}{s}:has(tr:nth-child(6)) td{{height:44px}}{s}:has(tr:nth-child(6)) td:first-child{{width:189px}}{s}:has(tr:nth-child(6)) td:last-child{{color:var(--n-7)}}{s} td.on{{background:var(--a1-7);color:var(--page)!important}}\n''')
# Model specification headers span both columns, above a light table surface.
s='[data-el="crossrail-table"]:has(thead th:nth-child(2)):not(:has(thead th:nth-child(3)))';f.write_text(f.read_text()+f'''\n{s}{{align-items:stretch}}{s} .table{{table-layout:fixed;background:var(--n-1);border:0;align-self:stretch}}{s} thead th{{height:65px;background:var(--a1-7);color:var(--page);border:0;padding:var(--gap);font-size:var(--type-26)}}{s} thead th:first-child{{text-align:left}}{s} thead th:last-child{{text-align:right}}{s} tbody td{{height:47px;padding:0 var(--gap);border:0;border-bottom:1px solid var(--n-3);font-size:var(--type-18);font-weight:var(--body-weight);text-align:left}}{s} tbody td:first-child{{font-weight:var(--name-weight)}}{s} tbody td:last-child{{text-align:right}}\n''')
# Annual calendar has actual highlighted dates and the two event captions.
f=p/'reassembled/slide_27.html';h=f.read_text();h=h.replace('<td class="num">15</td>','<td class="num on">15<small>리드회의</small></td>')
for v in range(16,21):h=h.replace(f'<td class="num">{v}</td>',f'<td class="num on">{v}'+('<small>성과 평가 기간</small>' if v==18 else '')+'</td>')
h=h.replace('마감 기한이 명시된 일정은 시간을 엄수해 주시기 바랍니다.</p></div></div>','마감 기한이 명시된 일정은 시간을 엄수해 주시기 바랍니다.</p></div><div class="item"><p class="name">마감 기한이 명시된 일정은 시간을 엄수해 주시기 바랍니다.</p></div></div>',1)
# The guide heading is a headline; the following four lines are a separate checklist.
a=h.index('<div class="list check"');b=h.index('<div class="tablebox ',a);old=h[a:b];names=re.findall('<p class="name">(.*?)</p>',old)
new=slot('<div class="headline" data-el="crossrail-headline"><h2>'+names[0]+'</h2></div>',1,6,3,1)+slot('<div class="list check" data-el="crossrail-list">'+''.join('<div class="item"><p class="name">'+x+'</p></div>' for x in names[1:])+'</div>',1,6,4,3);h=h[:a]+new+h[b:];f.write_text(h)
s='[data-el="crossrail-table"]:has(thead th:nth-child(7)):not(:has(thead th:nth-child(8)))';f=c/'elements/table/element.css';f.write_text(f.read_text()+f'''\n{s}{{position:relative;isolation:isolate;padding:0 var(--pad);align-items:stretch;transform:translateY(calc(var(--gap-sm)/-4))}}{s}::before{{content:"";position:absolute;inset:0 var(--gap-sm) 0 calc(var(--gap-sm)*4/3);background:var(--n-1);z-index:-1}}{s} .table{{height:100%;table-layout:fixed;border:0}}{s} th{{height:50px;padding:0;text-align:center;background:transparent!important;color:var(--ink)!important;font-family:var(--crossrail-font-label);font-size:var(--type-16);font-weight:var(--body-weight);border:0;border-bottom:1px solid var(--n-5)}}{s} th:first-child{{color:var(--warn)!important}}{s} td{{position:relative;height:67px;vertical-align:top;padding:0;text-align:center!important;font-family:var(--crossrail-font-label);font-size:var(--type-16);font-weight:var(--body-weight);background:transparent!important;color:var(--ink);border:0}}{s} td.on{{background:linear-gradient(var(--a1-7) 34px,var(--n-3) 34px)!important;color:var(--page)}}{s} td.on:first-of-type{{background:linear-gradient(var(--a2-7) 34px,var(--n-3) 34px)!important}}{s} td small{{display:block;margin-top:var(--gap-sm);font-size:var(--type-14);white-space:nowrap;color:var(--ink)}}\n''')
# Source calendar capsules are two-line labels, preserving their two different dates.
s='[data-el="crossrail-pill"]:has(.note):not(:has(.mark))';f=c/'elements/pill/element.css';f.write_text(f.read_text()+f'\n{s}{{max-height:86px;height:86px}}{s} .parts{{flex-direction:column;gap:calc(var(--gap-sm)/2)}}{s} .name{{font-size:var(--type-26);color:var(--n-5)}}{s} .note{{font-size:var(--type-18);font-weight:var(--name-weight);color:var(--ink)}}\n')
s='[data-el="crossrail-list"].check:not(:has(.note))';f=c/'elements/list/element.css';f.write_text(f.read_text()+f'''\n{s}{{justify-content:flex-start;gap:var(--gap);background:var(--n-1);padding:var(--gap);box-sizing:border-box}}{s} .item{{display:grid;grid-template-columns:28px 1fr;column-gap:var(--gap-sm)}}{s} .item::before{{grid-column:1;grid-row:1;width:24px;height:24px;margin-top:0;border:1px solid var(--n-5);transform:none}}{s} .item::after{{content:"";position:absolute;left:5px;top:3px;width:18px;height:10px;border-left:2px solid var(--ink);border-bottom:2px solid var(--ink);transform:rotate(-45deg)}}{s} .name{{grid-column:2;grid-row:1;font-size:var(--type-18);font-weight:var(--label-weight)}}\n''')
# Contact information is a compact key/value table and the full-width navy left rail.
rows=[['주소','미리시 미리구 미리대로 7001번 길'],['대표 전화','031-000-0000'],['이메일','miricompany @ 0000.com'],['홈페이지','www.000000.com'],['상담 시간','월~금 09:00~18:00']];setbody(30,slot(tab(rows),1,12,4,3))
s='[data-el="crossrail-table"]:not(:has(thead)):not(:has(tr>td:nth-child(3))):has(tr:nth-child(5):last-child)';f=c/'elements/table/element.css';f.write_text(f.read_text()+f'\n{s}{{padding-top:var(--pad);padding-left:var(--gap-sm)}}{s} td{{height:39px;border:0;color:var(--n-7)}}{s} td:first-child{{width:119px;color:var(--ink)}}\n')
f=c/'foundation/foundation.css';f.write_text(f.read_text()+'''\n.slide:has(.head.at-bottom-left) .body{grid-column:7 / span 6;grid-row:1 / span 2;padding-top:0}.slide:has(.head.at-bottom-left) .page::after{left:581px}.slide:has(.head.at-bottom-left) .head>.title{font-size:var(--type-76)}\n''')
print('equipment components, table hierarchy, calendar highlights/checklist and contact restored')
